/** Arrows and the play triangle read as plain text unless the model asked for the emoji form with U+FE0F. */
const TEXT_DEFAULT = new Set(['\u{25B6}', '\u{27A1}', '\u{2B05}', '\u{2B06}', '\u{2B07}', '\u{2197}', '\u{2198}', '\u{2199}', '\u{2196}', '\u{21A9}', '\u{21AA}', '\u{2194}', '\u{2195}']);

const SVG_NS = 'http://www.w3.org/2000/svg';

let emojiPattern: RegExp | undefined;

/** Longest first so multi-codepoint emoji win; optional VS16 and skin tone; never half of a ZWJ sequence. */
function getEmojiPattern(): RegExp {
	if (!emojiPattern) {
		const alternatives = Object.keys(EMOJI_ICONS)
			.sort((a, b) => b.length - a.length)
			.map(emoji => emoji.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + (TEXT_DEFAULT.has(emoji) ? '\\uFE0F' : '\\uFE0F?'));
		emojiPattern = new RegExp(`(?:${alternatives.join('|')})[\\u{1F3FB}-\\u{1F3FF}]?(?!\\u200D)`, 'gu');
	}
	emojiPattern.lastIndex = 0;
	return emojiPattern;
}

function baseEmoji(match: string): string {
	return match.replace(/\uFE0F|[\u{1F3FB}-\u{1F3FF}]/gu, '');
}

export function hasEmojiIcon(emoji: string): boolean {
	return !!EMOJI_ICONS[baseEmoji(emoji)];
}

/** An inline line icon, one line tall with a 1px stroke, standing in for `emoji`, or undefined when there is no match. */
export function renderEmojiIcon(doc: Document, emoji: string): SVGSVGElement | undefined {
	const entry = EMOJI_ICONS[baseEmoji(emoji)];
	const paths = entry && ICON_PATHS[entry[0]];
	if (!entry || !paths) {
		return undefined;
	}
	const svg = doc.createElementNS(SVG_NS, 'svg');
	svg.setAttribute('class', 'volt-emoji-icon');
	svg.setAttribute('viewBox', '0 0 24 24');
	svg.setAttribute('fill', 'none');
	svg.setAttribute('stroke', 'currentColor');
	svg.setAttribute('stroke-width', '1');
	svg.setAttribute('stroke-linecap', 'round');
	svg.setAttribute('stroke-linejoin', 'round');
	svg.setAttribute('role', 'img');
	svg.setAttribute('aria-label', emoji);
	svg.dataset.icon = entry[0];
	if (entry[1]) {
		svg.dataset.tone = entry[1];
	}
	for (const d of paths) {
		const path = doc.createElementNS(SVG_NS, 'path');
		path.setAttribute('d', d);
		// 1 CSS pixel whatever size the icon is drawn at
		path.setAttribute('vector-effect', 'non-scaling-stroke');
		svg.appendChild(path);
	}
	return svg;
}

const SKIP_SELECTOR = 'pre, code, .katex, .volt-md-code-host, svg, textarea, input';

/** Swaps known emoji in `root`'s text for line icons, leaving code, math and diagrams alone. */
export function replaceEmojiWithIcons(root: HTMLElement): void {
	const doc = root.ownerDocument;
	const walker = doc.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
		acceptNode: node => node.parentElement?.closest(SKIP_SELECTOR) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT,
	});
	const targets: Text[] = [];
	for (let node = walker.nextNode(); node; node = walker.nextNode()) {
		if (getEmojiPattern().test(node.nodeValue ?? '')) {
			targets.push(node as Text);
		}
	}
	for (const text of targets) {
		const value = text.nodeValue ?? '';
		const fragment = doc.createDocumentFragment();
		let last = 0;
		for (const match of value.matchAll(getEmojiPattern())) {
			const icon = renderEmojiIcon(doc, match[0]);
			if (!icon) {
				continue;
			}
			if (match.index > last) {
				fragment.appendChild(doc.createTextNode(value.slice(last, match.index)));
			}
			fragment.appendChild(icon);
			last = match.index + match[0].length;
		}
		if (last === 0) {
			continue;
		}
		if (last < value.length) {
			fragment.appendChild(doc.createTextNode(value.slice(last)));
		}
		text.replaceWith(fragment);
	}
}
